def identity_key_for_profile(universe_key):
    """Deterministic identity key: the existing specialized profile key.

    This is a copy, not a hash and not a name. Two profiles that already
    share a key collide. They are never merged.
    """
    return universe_key


def backfill_staff_identities(apps, schema_editor):
    Identity = apps.get_model('universe', 'UniverseStaffIdentity')
    GM = apps.get_model('universe', 'UniverseGM')
    Coach = apps.get_model('universe', 'UniverseCoach')
    pending = []
    claimed = {}
    for kind, model in (('GM', GM), ('coach', Coach)):
        for row in model.objects.all().order_by('pk'):
            key = identity_key_for_profile(row.universe_key)
            if not key or not row.name:
                raise RuntimeError(
                    'Staff identity backfill refused empty %s id %s. '
                    'No identity was invented.'
                    % (kind, row.pk)
                )
            owner = claimed.get(key)
            if owner is not None:
                raise RuntimeError(
                    'Staff identity key %r collides between %s and %s id %s. '
                    'Existing GM and coach rows are not merged by key, name, '
                    'or birth year.'
                    % (key, owner, kind, row.pk)
                )
            claimed[key] = '%s id %s' % (kind, row.pk)
            pending.append((model, row.pk, row.release_id, key, row.name, row.birth_year))
    for model, pk, release_id, key, name, birth_year in pending:
        identity = Identity.objects.create(
            release_id=release_id,
            universe_key=key,
            name=name,
            birth_year=birth_year,
        )
        updated = model.objects.filter(pk=pk, identity__isnull=True).update(
            identity_id=identity.pk,
        )
        if updated != 1:
            raise RuntimeError(
                'Staff identity backfill could not attach profile id %s. '
                'No people were merged.'
                % pk
            )


